<script setup lang="ts">
import * as BoxunAccountPaymentApi from './BoxunAccountPaymentApi'

type BoxunAccountPaymentFormData = Parameters<typeof BoxunAccountPaymentApi.createBoxunAccountPayment>[0]
type EntityId = string | number


defineOptions({ name: 'BoxunAccountPaymentForm' })

const emit = defineEmits<{ success: [] }>()
const message = useMessage()
const { t } = useI18n()
const dialogVisible = ref(false)
