const initialFormData = () => ({
  username: '',
  paymentAmount: undefined,
  paymentTime: undefined,
  expirationTime: undefined,
  orderNumber: '',
  accountType: undefined,
  businessDescription: '',
  orderPaymentStatus: undefined
}) as BoxunAccountPaymentFormData
const formData = ref(initialFormData())
const formRules = reactive({

})






const open = async (type: 'create' | 'update', id?: EntityId, defaults?: Partial<BoxunAccountPaymentFormData>) => {

  formType.value = type
  editingId.value = id

  dialogTitle.value = type === 'create' ? '新增账户支付状态' : '修改账户支付状态'
  formData.value = { ...initialFormData(), ...defaults }
  formLoading.value = true
  dialogVisible.value = true
  try {


    if (id !== undefined) {
      formData.value = { ...initialFormData(), ...await BoxunAccountPaymentApi.getBoxunAccountPayment(id) }

    }


  } finally {
    formLoading.value = false
    await nextTick()
    formRef.value?.clearValidate()

  }
}
defineExpose({ open })


const submitForm = async () => {
  if (formLoading.value) return



  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) {

    return
  }
  const inputFields = formType.value === 'create' ? ['username', 'paymentAmount', 'paymentTime', 'expirationTime', 'orderNumber', 'accountType', 'businessDescription', 'orderPaymentStatus'] : ['id', 'username', 'paymentAmount', 'paymentTime', 'expirationTime', 'orderNumber', 'accountType', 'businessDescription', 'orderPaymentStatus']
  const input = Object.fromEntries(inputFields.map((key) => [key, formData.value[key]]))
  if ('paymentTime' in input) input.paymentTime = formData.value.paymentTime ? String(formData.value.paymentTime).replace(' ', 'T') : null
  if ('expirationTime' in input) input.expirationTime = formData.value.expirationTime ? String(formData.value.expirationTime).replace(' ', 'T') : null
  formLoading.value = true
  try {
    if (formType.value === 'create') {
      await BoxunAccountPaymentApi.createBoxunAccountPayment(input)
      message.success(t('common.createSuccess'))
